def evaluate(current_reputation, observation, my_history, round_num):
    # Compute own cooperation rate from personal history
    if len(my_history) == 0:
        own_coop_rate = 0.5  # neutral default
    else:
        own_coop_rate = sum(1 for a in my_history if a) / len(my_history)

    # Reputation update depends on own behavior
    if observation['action'] == 'cooperate':
        # Increase reputation; more if we are cooperative ourselves
        increment = 0.20 + 0.10 * own_coop_rate
        new_reputation = current_reputation + increment * (1.0 - current_reputation)
    else:
        # Decrease reputation; more sharply if we are not cooperative
        decrement = 0.40 - 0.10 * own_coop_rate
        new_reputation = current_reputation - decrement * (1.0 + current_reputation)

    return max(-1.0, min(1.0, new_reputation))


