def decide(recipient_reputation, round_num, my_history):
    # Core threshold rises more slowly and starts lower
    threshold = -0.3 + (round_num / 15.0) * 0.6  # range: -0.3 to 0.3

    # Use own recent history (last 3 rounds) to adjust cooperativeness
    # If we have defected more than once recently, become extra cooperative
    recent_defections = sum(1 for act in my_history[-3:] if not act)  # False = defect
    if recent_defections >= 2:
        threshold -= 0.2   # lower threshold, cooperate more readily

    # Also, in very early rounds, be slightly more generous
    if round_num <= 3:
        threshold -= 0.1

    return recipient_reputation > threshold
